import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    times = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(times)}
    m = len(times)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, p in jobs:
        add_edge(idx[s], idx[e], 1, -p)

    # Initial Johnson potentials via DAG shortest paths from 0.
    pot = [0] * m
    for u in range(m - 1):
        pu = pot[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    INF = 10**18
    total_cost = 0

    for _ in range(k):
        dist = [INF] * m
        parent_v = [-1] * m
        parent_e = [-1] * m
        dist[0] = 0
        pq: list[tuple[int, int]] = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[m - 1] >= 0:
            break

        total_cost += pot[m - 1]
        cur = m - 1
        while cur != 0:
            u = parent_v[cur]
            ei = parent_e[cur]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[cur][edge[3]][1] += 1
            cur = u

    return -total_cost
